export const schema=JSON.parse(readFileSync(new URL('./schema.json',import.meta.url),'utf8'));
const streamSchema=schema.properties.readonly.anyOf[1],same=(a,b)=>assert.deepEqual(a,b);
export function admitPins(observed,expected){try{same(observed,expected);return true;}catch{return false;}}
export function makeRecord(binding,e){
 return {purpose:'afw.readonly-source-site.safe.v1',sourceBase:'327e9b7ec2182588dfb02e58b238787abb37a017',source:e.GITHUB_SHA,sourceTree:binding?.sourceTree??null,run:e.GITHUB_RUN_ID,attempt:1,job:'readonly',node:process.versions.node==='22.23.4'?'22.23.4':'unknown',stage:'setup',programProof:{verified:binding?.programsVerified===true,count:binding?.programCount??0,setSha256:binding?.programSetSha256??null,payloadExpandedSha256:binding?.payloadExpandedSha256??null,coreGitVerified:binding?.coreGitVerified===true,prefixVerified:binding?.prefixVerified===true},sourceProof:{mapBlob:schema.properties.sourceProof.properties.mapBlob.enum[0],mapSha256:schema.properties.sourceProof.properties.mapSha256.enum[0],mapVerified:false,worldBeforeVerified:false,nativeBeforeVerified:false,worldAfterVerified:false,nativeAfterVerified:false,originalBodiesUnchanged:false},controls:{passed:false,count:0,expected:6,usableShape:false,usableColumns:false},pure:{passed:false,cases:0,expected:8},profile:{passed:false,group:'readonly'},businessCommand:{started:false,ended:false,exitCode:null,signal:'none'},readonly:null,collectionComplete:false,usableLocationCount:0,...flags()};
}
export function validateStream(q){
 validate(q,streamSchema);same(q.rows.map(x=>x.case),['R1','R2','R3']);
 for(const row of q.rows)assert((row.result==='failed')===(row.error!==null));
 const errors=[...q.rows.map(x=>x.error),q.precase?.error].filter(Boolean);
 for(const error of errors)if(error.causeCode!=='ERR_ASSERTION')assert.equal(error.sourceSite,'unknown');
 const first=q.precase?{target:'native_file',error:q.precase.error}:q.rows.filter(x=>x.result==='failed').map(x=>({target:x.case,error:x.error}))[0]??null;same(q.firstFailure,first);
 if(q.valid){
  assert(q.ended&&q.summary&&q.state!=='unknown');for(const error of errors)assert(!['testTimeoutFailure','cancelledByParent','testAborted'].includes(error.wrapperFailureType));const file=q.state==='file_failure';
  if(file)assert(q.precase?.result==='failed'&&q.rows.every(x=>x.result==='not_observed'));
  else assert(q.precase===null&&q.rows.every(x=>['passed','failed'].includes(x.result)));
  const pass=file?0:q.rows.filter(x=>x.result==='passed').length,fail=file?1:3-pass;
  same(q.summary.counts,{cancelled:0,failed:fail,passed:pass,skipped:0,suites:0,tests:file?1:3,todo:0,topLevel:file?1:3});
  assert.equal(q.summary.success,fail===0);assert.equal(q.state,file?'file_failure':fail?'case_failure':'all_pass');
 }else assert(q.state==='unknown'&&q.summary===null);
 return q;
}
export function knownLocations(q){return q?[...q.rows.map(x=>x.error),q.precase?.error].filter(x=>x&&x.sourceSite!=='unknown').length:0;}
export function revokeLocations(r){
 const q=r.readonly;
 if(q){for(const error of [...q.rows.map(x=>x.error),q.precase?.error,q.firstFailure?.error].filter(Boolean))error.sourceSite='unknown';}
 for(const k of ['worldAfterVerified','nativeAfterVerified','originalBodiesUnchanged'])r.sourceProof[k]=false;
 r.usableLocationCount=0;r.collectionComplete=false;r.stage='unknown';return r;
}
export function validateRecord(r,context){
 validate(r,schema);
 if(context){assert.equal(context.attempt,1);for(const [key,value]of Object.entries({source:context.source,sourceTree:context.tree,run:context.run,job:'readonly'}))assert.equal(r[key],value);}
 const n=r.businessCommand,p=r.sourceProof,proof=r.programProof;
 if(proof.verified){assert(context&&context.programCount===18&&/^[a-f0-9]{64}$/.test(context.programSetSha256)&&/^[a-f0-9]{64}$/.test(context.payloadExpandedSha256));assert.equal(proof.count,18);assert.equal(proof.setSha256,context.programSetSha256);assert.equal(proof.payloadExpandedSha256,context.payloadExpandedSha256);}
 if(r.controls.passed)assert(r.controls.count===6&&r.controls.usableShape&&r.controls.usableColumns);
 if(r.pure.passed)assert(r.controls.passed&&r.pure.cases===8);
 if(r.profile.passed)assert(r.pure.passed);
 if(n.started===true)assert(r.node==='22.23.4'&&r.programProof.verified&&r.programProof.coreGitVerified&&r.programProof.prefixVerified&&p.mapVerified&&p.worldBeforeVerified&&p.nativeBeforeVerified&&r.controls.passed&&r.pure.passed&&r.profile.passed);
 else assert(n.ended===false&&n.exitCode===null&&r.readonly===null);
 if(n.ended)assert(n.started===true);
 if(['SIGTERM','SIGKILL','SIGINT'].includes(n.signal))assert(n.started===true&&n.ended===true);
 if(n.started===false)assert.equal(n.signal,'none');
 if(n.started===null)assert.equal(n.signal,'unknown');
 if(n.exitCode!==null)assert(n.ended&&n.signal==='none');
 if(r.readonly){validateStream(r.readonly);if(r.readonly.valid){assert(n.ended&&n.signal==='none');assert.equal(n.exitCode===0,r.readonly.summary.success);}}
 assert.equal(r.usableLocationCount,knownLocations(r.readonly));
 if(r.usableLocationCount>0)assert(p.mapVerified&&p.worldBeforeVerified&&p.nativeBeforeVerified&&p.worldAfterVerified&&p.nativeAfterVerified&&p.originalBodiesUnchanged);
 assert.equal(r.collectionComplete,r.stage==='complete');
 if(r.stage==='complete')assert(n.started===true&&n.ended&&n.signal==='none'&&Number.isSafeInteger(n.exitCode)&&r.readonly?.valid===true&&p.worldBeforeVerified&&p.nativeBeforeVerified&&p.worldAfterVerified&&p.nativeAfterVerified&&p.originalBodiesUnchanged&&p.mapVerified);
 if(r.stage==='hold')assert(n.started===false);
 return r;
}
