const reject=fn=>assert.throws(fn),clone=x=>JSON.parse(JSON.stringify(x)),path=resolve(root,'tiny-helper.mjs'),url=pathToFileURL(path).href;
const line='    at helper ('+path+':3:26)',header=message=>'AssertionError [ERR_ASSERTION]: '+message;
function wrapped(message='probe',suffix=line){return {failureType:'testCodeFailure',cause:{code:'ERR_ASSERTION',message,stack:header(message)+'\n'+suffix,operator:'strictEqual',actual:false,expected:true}};}
function stream(site='world_1188_a4'){
 const collector=createCollector('/native.test','native.test',()=>site),error=wrapped();
 for(const id of ['R1','R2','R3'])collector.ingest({type:'test:fail',data:{name:id+' fixed original SDK readonly budget',nesting:0,details:{error,type:'test'}}});
 collector.ingest({type:'test:summary',data:{counts:{cancelled:0,failed:3,passed:0,skipped:0,suites:0,tests:3,todo:0,topLevel:3},success:false}});
 return collector.finish(true);
}
try{
 assert.equal(process.versions.node,'22.23.4');
 const actual=await node(['--test','--test-concurrency=1','--test-reporter=tap','--test-reporter='+join(root,'tiny-reporter.mjs'),'--test-reporter-destination=stdout','--test-reporter-destination='+join(root,'tiny-result.json'),join(root,'tiny.test.mjs')],{log:join(root,'tiny-private.tap')});
 assert(actual.started===true&&actual.ended&&actual.signal==='none'&&actual.exitCode===1);
 const observed=json(join(root,'tiny-result.json'));assert.equal(observed.purpose,'afw.readonly-source-site.tiny.v1');assert(observed.valid&&observed.ended&&observed.usableShape);
 result.usableShape=true;pass('C1');
